package com.jobpilot.user;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="users") public class User{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=120)private String name;@Column(nullable=false,unique=true,length=160)private String email;@Column(nullable=false)private String password;@Column(nullable=false)private boolean alertsEnabled=true;@Column(nullable=false)private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public boolean isAlertsEnabled(){return alertsEnabled;}public void setAlertsEnabled(boolean v){alertsEnabled=v;}}
